def assign_existing_onboarding_tasks(apps, schema_editor):
    Task = apps.get_model('onboardingapp', 'OnboardingTask')
    for task in Task.objects.select_related(
        'case', 'case__employee', 'case__started_by',
        'case__employee__reporting_manager', 'source_template_task',
    ).all():
        if task.owner_type == 'EMPLOYEE':
            assignee_id = task.case.employee_id
        elif task.owner_type == 'HR':
            assignee_id = task.case.started_by_id
        elif task.owner_type == 'MANAGER':
            assignee_id = task.case.employee.reporting_manager_id
        else:
            assignee_id = task.source_template_task.owner_employee_id if task.source_template_task_id else None
        if assignee_id:
            Task.objects.filter(pk=task.pk).update(assigned_to_id=assignee_id)


